SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, a.discharge_location, a.deathtime, a.los, COUNT(CASE WHEN a.discharge_location = 'home' THEN 1 END)::FLOAT / NULLIF(COUNT(a.subject_id), 0) AS proportion_home, COUNT(CASE WHEN a.discharge_location = 'hospice' THEN 1 END)::FLOAT / NULLIF(COUNT(a.subject_id), 0) AS proportion_hospice, COUNT(CASE WHEN a.deathtime <= a.admittime + INTERVAL '14 days' THEN 1 END)::FLOAT / NULLIF(COUNT(a.subject_id), 0) AS proportion_death_within_14_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 80 AND 90 AND a.admission_type != 'emergency' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, a.discharge_location, a.deathtime, a.los ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.admission_type, a.discharge_location, a.deathtime, a.los NULLS LAST;